// Separa cada mail de alerta en ofertas individuales — dispatcher por
// remitente, porque cada sitio arma el mail totalmente distinto (verificado
// contra mails reales del 2026-09-07: Indeed = 1 oferta/mail con datos
// reales de empresa/puesto/ubicación en el cuerpo; Bumeran = batch sin link
// en texto plano, requiere el html del mail). Computrabajo se sacó del
// filtro de Gmail — sus mails son puro teaser sin datos de oferta ("Empresas
// buscan talento para puestos de X, postulate ahora" + link a un grid de
// búsqueda), no hay nada que extraer.
//
// ASUNCIÓN SIN VALIDAR (igual que el split de LinkedIn de la v1): los
// nombres de campo item.json.from / item.json.subject / item.json.textHtml
// son el formato esperado del nodo Gmail en esta instancia de n8n — no se
// pudo confirmar contra una ejecución real todavía. Si "Aplicar tope de
// seguridad" reporta 0 ofertas de una fuente que sabés que llegó, revisar
// acá primero.

function textoDe(item) {
  return item.json.textPlain || item.json.text || item.json.snippet || '';
}
function htmlDe(item) {
  return item.json.textHtml || item.json.html || '';
}
function remitenteDe(item) {
  return String(item.json.from || item.json.sender || '').toLowerCase();
}

function parsearLinkedIn(item) {
  const cuerpo = textoDe(item);
  const regexLink = /https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/\d+[^\s)>\]]*/g;
  const matches = [...cuerpo.matchAll(regexLink)];
  if (matches.length === 0) return [{ link: null, texto_oferta: cuerpo.trim(), fuente: 'linkedin' }];
  const out = [];
  for (let i = 0; i < matches.length; i++) {
    const inicio = i === 0 ? 0 : matches[i - 1].index + matches[i - 1][0].length;
    const fin = matches[i].index + matches[i][0].length;
    out.push({ link: matches[i][0], texto_oferta: cuerpo.slice(inicio, fin).trim(), fuente: 'linkedin' });
  }
  return out;
}

function parsearIndeed(item) {
  // 1 oferta por mail — empresa/puesto vienen en el subject, no en el cuerpo.
  // link queda null a propósito: el link de Indeed es un redirect
  // cts.indeed.com de un solo uso, no sirve como referencia estable. El
  // dedup usa empresa+puesto (normalizarEmpresaPuesto), no el link.
  const cuerpo = textoDe(item);
  const asunto = item.json.subject || '';
  return [{ link: null, texto_oferta: (asunto + '\n\n' + cuerpo).trim(), fuente: 'indeed' }];
}

function parsearBumeran(item) {
  // El texto plano NO trae links (se pierden al convertir el mail a texto
  // plano) — hace falta el html. Sin validar todavía contra el HTML real:
  // en vez de inventar una estructura, esto cae a NO_PARSEABLE (revisar a
  // mano) hasta confirmar el HTML real y escribir el split de tarjetas.
  const cuerpoHtml = htmlDe(item);
  if (!cuerpoHtml) {
    return [{ link: null, texto_oferta: '', fuente: 'bumeran', error_parseo_mail: true, detalle_error: 'Sin campo html en el item de Gmail — no se puede sacar el link de Bumeran del texto plano.' }];
  }
  return [{ link: null, texto_oferta: textoDe(item).trim(), fuente: 'bumeran', error_parseo_mail: true, detalle_error: 'Parser de Bumeran pendiente de validar contra HTML real — cae a revisión manual.' }];
}

const items = [];
const entrada = $input.all();
for (let idx = 0; idx < entrada.length; idx++) {
  const item = entrada[idx];
  try {
    const remitente = remitenteDe(item);
    let ofertas;
    if (remitente.includes('linkedin.com')) ofertas = parsearLinkedIn(item);
    else if (remitente.includes('indeed.com')) ofertas = parsearIndeed(item);
    else if (remitente.includes('bumeran.com')) ofertas = parsearBumeran(item);
    else ofertas = [{ link: null, texto_oferta: textoDe(item).trim(), fuente: 'desconocida' }];

    // pairedItem explicito: sin esto n8n no puede rastrear de que mail vino
    // cada oferta, y $('Parsear ofertas').item devuelve el item equivocado.
    for (const oferta of ofertas) items.push({ json: oferta, pairedItem: { item: idx } });
  } catch (e) {
    items.push({ json: { link: null, texto_oferta: '', fuente: 'error', error_parseo_mail: true, detalle_error: String((e && e.message) || e) }, pairedItem: { item: idx } });
  }
}

return items;

// Tope duro de ofertas procesadas por corrida, para que un día raro (mail
// mal filtrado, alerta que trae 200 avisos) no genere una factura
// inesperada de la API de Claude. Cambiá este número si el volumen normal
// de alertas crece — es la única variable que hay que tocar.
const MAX_OFERTAS_POR_CORRIDA = 30;

const items = $input.all();
const totalDetectado = items.length;
const excedeTope = totalDetectado > MAX_OFERTAS_POR_CORRIDA;
const procesar = excedeTope ? items.slice(0, MAX_OFERTAS_POR_CORRIDA) : items;

// El flag va en todos los items que siguen para que "Armar mail resumen"
// (que corre una sola vez al final) pueda mostrar el aviso sin nodos extra.
return procesar.map((item, i) => ({
  json: {
    ...item.json,
    _tope_alcanzado: excedeTope,
    _total_detectado: totalDetectado,
    _procesadas: procesar.length,
  },
  // preservar el rastro del item original, si no se rompe $('...').item
  pairedItem: item.pairedItem !== undefined ? item.pairedItem : { item: i },
}));

// Se llega aca cuando 'Extraer datos con IA' agoto los reintentos (429, 529,
// timeout, red). Mismo criterio de link que en 'Parsear respuesta IA'.
let linkOriginal = null;
try { linkOriginal = $('Preparar prompt IA').item.json.link; } catch (e) { linkOriginal = null; }
return {
  json: {
    error_extraccion: true,
    link: linkOriginal,
    respuesta_cruda: { error: ($json && $json.error) || $json },
  },
};

// El link se lee de 'Preparar prompt IA', que esta a UN nodo de distancia y
// corre en modo runOnceForEachItem: n8n mantiene el pareo de items intacto.
// Antes leia de 'Parsear ofertas', 4 nodos atras y cruzando dos Code nodes
// que cambian la cantidad de items -- ahi el pareo se pierde y el link que
// llegaba al Sheet era el de OTRA oferta.
let oferta;
try {
  const texto = $json.content && $json.content[0] ? $json.content[0].text : '';
  const textoLimpio = texto.replace(/```json\s*|```/g, '').trim();
  oferta = JSON.parse(textoLimpio);
} catch (e) {
  oferta = null;
}

let linkOriginal = null;
try { linkOriginal = $('Preparar prompt IA').item.json.link; } catch (e) { linkOriginal = null; }

if (!oferta || typeof oferta !== 'object') {
  return { json: { error_extraccion: true, link: linkOriginal, respuesta_cruda: $json } };
}

oferta.link = linkOriginal || oferta.link || null;
return { json: oferta };

// Mirror de reglas.js — si cambias una regla, cambiala ahi primero, corre
// `node --test tests/` y despues pegala aca.
const MAX_ANIOS_TOLERADO = 3;
const MAX_POSTULANTES_BAJA_COMPETENCIA = 25;
const MAX_ANTIGUEDAD_HORAS_BAJA_COMPETENCIA = 6;
const MIN_COINCIDENCIAS_STACK = 2;

// Stack real de Simon. Editar a mano cuando cambie el CV.
const CANDIDATO_STACK = ['react','node','express','javascript','typescript','postgres','postgresql','supabase','n8n','docker','python','flutter','angular','html','css','wordpress'];

// OJO: antes esta lista tenia 'junior' y 'entry level' sueltos, y como
// alcanzaba con que la palabra apareciera en cualquier frase, descartaba
// justo los avisos que te sirven ("Junior Developer", "entry level welcome").
// Ahora solo frases que de verdad excluyen.
const TERMINOS_EXCLUYEN_PERFIL = [
  'no junior','not junior','no juniors','not looking for junior','sin junior',
  'senior only','solo senior','only senior','no entry level','no bootcamp',
  'do not apply if','no apliques si','must have 5','5+ years required'
];

// Titulos que NO tenes. Una tecnicatura en curso no te excluye de un aviso
// que pide "tecnicatura" — antes descartaba por cualquier titulo excluyente.
const TITULOS_QUE_NO_TENES = ['grado','licenciatura','maestria','master','bachelor','ingenieria','ingeniero','phd','doctorado'];

function norm(t) {
  return String(t === null || t === undefined ? '' : t)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizarEmpresaPuesto(empresa, puesto) {
  const n = (t) => norm(t)
    .replace(/\b(s\.?a\.?|s\.?r\.?l\.?|inc\.?|ltd\.?|llc\.?)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  return n(empresa) + '::' + n(puesto);
}

function contarCoincidenciasStack(ofertaStack) {
  const stackOferta = (Array.isArray(ofertaStack) ? ofertaStack : []).map(norm).filter((t) => t.length >= 2);
  return CANDIDATO_STACK.filter((tech) => stackOferta.some((t) => t === tech || t.includes(tech))).length;
}

function fraseExcluyePerfil(frasesExclusion) {
  const texto = norm((Array.isArray(frasesExclusion) ? frasesExclusion : []).join(' '));
  return TERMINOS_EXCLUYEN_PERFIL.find((t) => texto.includes(t)) || null;
}

function tituloQueNoTenes(tituloRequerido) {
  const t = norm(tituloRequerido);
  if (!t) return null;
  return TITULOS_QUE_NO_TENES.find((x) => t.includes(x)) || null;
}

// Construye la fila que va al Sheet. TODOS los campos existen siempre y son
// string o numero — nunca undefined. Esta es la razon por la que el Sheet
// escribia basura: el mapeo hacia $json.stack.join(', ') y en los items con
// error 'stack' no existia.
function fila(o, estado, motivo, dedupKey) {
  const s = (v) => (v === null || v === undefined) ? '' : String(v);
  const n = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? '' : Number(v);
  const base = o || {};
  return {
    dedup_key: dedupKey,
    fecha_detectada: new Date().toISOString().slice(0, 19).replace('T', ' '),
    empresa: s(base.empresa),
    puesto: s(base.puesto),
    modalidad: s(base.modalidad),
    tipo_contrato: s(base.tipo_contrato),
    horas_semanales: n(base.horas_semanales),
    salario_min: n(base.salario_min),
    salario_max: n(base.salario_max),
    salario_moneda: s(base.salario_moneda),
    anios_experiencia_min: n(base.anios_experiencia_min),
    stack: Array.isArray(base.stack) ? base.stack.join(', ') : '',
    postulantes: n(base.postulantes),
    antiguedad_horas: n(base.antiguedad_horas),
    confianza_extraccion: n(base.confianza_extraccion),
    link: s(base.link),
    estado: estado,
    motivo: motivo,
    // interno, para ordenar el mail resumen. No se mapea al Sheet.
    // Los datos del tope NO se leen aca: el nodo HTTP reemplaza el json
    // entero, asi que _tope_alcanzado muere antes de llegar. El mail lo lee
    // directo de 'Aplicar tope de seguridad'.
    _horas_raw: (base.horas_semanales === null || base.horas_semanales === undefined) ? null : Number(base.horas_semanales),
  };
}

// dedup_key unica por item aun dentro del mismo milisegundo.
let contadorError = 0;
function dedupKeyError(link) {
  contadorError++;
  return 'no_parseable::' + (link || 'sin-link') + '::' + Date.now() + '-' + contadorError + '-' + Math.random().toString(36).slice(2, 8);
}

try {
  const oferta = $json;

  if (oferta.error_extraccion) {
    return { json: fila(oferta, 'NO_PARSEABLE', 'El modelo no devolvio JSON valido (o la llamada fallo tras reintentos) — revisar a mano.', dedupKeyError(oferta.link)) };
  }

  const dedupKey = normalizarEmpresaPuesto(oferta.empresa, oferta.puesto);

  let vistas = [];
  try { vistas = $('Leer ofertas ya vistas').all().map((i) => i.json); } catch (e) { vistas = []; }
  const yaPostulado = vistas.some((v) => v && v.dedup_key === dedupKey && String(v.postulado).toLowerCase() === 'true');

  let estado, motivo;

  if (yaPostulado) {
    estado = 'DESCARTAR';
    motivo = 'Ya te postulaste a este puesto en esta empresa.';
  } else if (Number(oferta.anios_experiencia_min) > MAX_ANIOS_TOLERADO && oferta.anios_excluyente === true) {
    estado = 'DESCARTAR';
    motivo = 'Pide ' + oferta.anios_experiencia_min + '+ anios de experiencia de forma excluyente.';
  } else if (oferta.titulo_excluyente === true && tituloQueNoTenes(oferta.titulo_requerido)) {
    estado = 'DESCARTAR';
    motivo = 'Pide titulo (' + (oferta.titulo_requerido || 'sin especificar') + ') de forma excluyente y no lo tenes.';
  } else {
    const frase = fraseExcluyePerfil(oferta.frases_exclusion);
    if (frase) {
      const cita = (oferta.frases_exclusion || []).find((f) => norm(f).includes(frase)) || frase;
      estado = 'DESCARTAR';
      motivo = 'El aviso excluye tu perfil: "' + cita + '"';
    } else {
      const coincidencias = contarCoincidenciasStack(oferta.stack);
      const coincidenciaReal = coincidencias >= MIN_COINCIDENCIAS_STACK;
      const seniales = [];
      if (oferta.postulantes !== null && oferta.postulantes !== undefined && Number(oferta.postulantes) < MAX_POSTULANTES_BAJA_COMPETENCIA) seniales.push(oferta.postulantes + ' postulantes');
      if (oferta.antiguedad_horas !== null && oferta.antiguedad_horas !== undefined && Number(oferta.antiguedad_horas) < MAX_ANTIGUEDAD_HORAS_BAJA_COMPETENCIA) seniales.push('publicada hace ' + oferta.antiguedad_horas + 'hs');
      if (oferta.postulacion_rapida === true) seniales.push('postulacion rapida disponible');

      if (coincidenciaReal && seniales.length > 0) {
        estado = 'POSTULAR YA';
        motivo = 'Stack coincide (' + coincidencias + ' tecnologias) y competencia baja: ' + seniales.join(', ') + '.';
      } else if (!coincidenciaReal) {
        estado = 'MIRAR';
        motivo = 'Stack no coincide lo suficiente (' + coincidencias + '/' + MIN_COINCIDENCIAS_STACK + ' tecnologias).';
      } else {
        estado = 'MIRAR';
        motivo = 'Sin datos de competencia — incierto, no se asume baja competencia.';
      }
    }
  }

  return { json: fila(oferta, estado, motivo, dedupKey) };
} catch (e) {
  return { json: fila($json, 'NO_PARSEABLE', 'Error inesperado aplicando reglas: ' + String((e && e.message) || e) + ' — revisar a mano.', dedupKeyError($json ? $json.link : null)) };
}

// Lee de "Aplicar reglas de decision", NO de la salida de "Guardar en Sheet".
// El nodo de Google Sheets devuelve solo las columnas mapeadas, asi que los
// campos internos (_tope_alcanzado, _horas_raw) se perdian y el aviso de tope
// nunca aparecia.
let items = [];
try { items = $('Aplicar reglas de decisión').all().map((i) => i.json); }
catch (e) { items = $input.all().map((i) => i.json); }

const orden = (a, b) => {
  const d = (x) => (x._horas_raw === null || x._horas_raw === undefined) ? 999 : Math.abs(x._horas_raw - 20);
  return d(a) - d(b);
};

const postularYa = items.filter((o) => o.estado === 'POSTULAR YA').sort(orden);
const mirar = items.filter((o) => o.estado === 'MIRAR').sort(orden);
const noParseables = items.filter((o) => o.estado === 'NO_PARSEABLE');
const descartadas = items.filter((o) => o.estado === 'DESCARTAR');

// El tope se lee de su propio nodo. No viaja en los items porque el nodo
// HTTP de Anthropic reemplaza el json entero a mitad del camino.
let tope = {};
try { tope = $('Aplicar tope de seguridad').first().json || {}; } catch (e) { tope = {}; }
const topeAlcanzado = tope._tope_alcanzado === true;

const esc = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const avisoTope = !topeAlcanzado ? '' :
  '<p style="background:#fee2e2;padding:8px;border-radius:4px;">Tope de seguridad alcanzado: se detectaron ' +
  (tope._total_detectado || 0) + ' ofertas y se procesaron ' + (tope._procesadas || 0) +
  '. Revisa el resto a mano en Gmail.</p>';

const filaOferta = (o) => '<tr><td style="padding:6px;border-bottom:1px solid #eee;">' +
  (o.link ? '<a href="' + esc(o.link) + '">' : '') +
  esc(o.puesto || '(sin puesto)') + ' — ' + esc(o.empresa || '(sin empresa)') +
  (o.link ? '</a>' : '') +
  (o.horas_semanales ? ' (' + esc(o.horas_semanales) + 'hs/sem)' : '') +
  '</td><td style="padding:6px;border-bottom:1px solid #eee;">' + esc(o.motivo) + '</td></tr>';

const filaNoParseable = (o) => '<tr><td style="padding:6px;border-bottom:1px solid #eee;">' +
  (o.link ? '<a href="' + esc(o.link) + '">' + esc(o.link) + '</a>' : '(sin link)') +
  '</td><td style="padding:6px;border-bottom:1px solid #eee;">' + esc(o.motivo) + '</td></tr>';

const seccion = (titulo, lista, fn) => lista.length === 0 ? '' :
  '<h2 style="font-size:16px;">' + titulo + ' (' + lista.length + ')</h2><table style="width:100%;border-collapse:collapse;">' +
  lista.map(fn || filaOferta).join('') + '</table>';

const html = '<div style="font-family:sans-serif;max-width:640px;">' +
  avisoTope +
  seccion('Postular ya', postularYa) +
  seccion('Mirar', mirar) +
  seccion('No se pudo procesar — revisar a mano', noParseables, filaNoParseable) +
  '<p>Descartadas: ' + descartadas.length + '</p>' +
  '</div>';

return [{ json: { asunto: 'Radar de empleos — ' + postularYa.length + ' para postular ya', html: html } }];
